import{_ as a,y as n,a as s,o as i,a2 as t,D as o}from"./chunks/framework.DCcmcJcL.js";const p=JSON.parse('{"title":"File Management","description":"","frontmatter":{},"headers":[],"relativePath":"configure/file-management.md","filePath":"configure/file-management.md","lastUpdated":1789441803000}'),l={name:"configure/file-management.md"};function d(g,e,h,c,u,f){const r=n("ImagePopup");return i(),s("div",null,[e[0]||(e[0]=t('<h1 id="file-management" tabindex="-1">File Management <a class="header-anchor" href="#file-management" aria-label="Permalink to &quot;File Management&quot;">​</a></h1><p>Uploaded files, such as product images, category banners and the logos in your settings, are stored on the server by default. If your store runs on more than one server, or you would rather keep files in object storage, you can store them in Amazon S3 or Cloudflare R2 instead. The <strong>File Management</strong> group has three screens, and every setting on them applies to the whole store.</p><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><ol><li>Go to <strong>Configure &gt;&gt; File Management &gt;&gt; General</strong>.</li><li>In <strong>Settings</strong>, choose the <strong>Default Storage Driver</strong>.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',4)),o(r,{src:"/images/configure/file-management-general.png",alt:"General screen of the File Management group with the Default Storage Driver field"}),e[1]||(e[1]=t('<p><strong>Default Storage Driver:</strong> Where files uploaded from now on are saved and served from:</p><ul><li><strong>File (Local Storage)</strong> – the server&#39;s own disk. This is the default.</li><li><strong>Amazon S3</strong> – an Amazon S3 bucket, or a bucket in any service that works with the S3 API. Set it up on the <strong>Amazon S3</strong> screen first.</li><li><strong>Cloudflare R2</strong> – a Cloudflare R2 bucket. Set it up on the <strong>Cloudflare R2</strong> screen first.</li></ul><p>The <strong>Storage</strong> card on the <a href="./about.html">About</a> screen shows which driver is in use.</p><h3 id="files-already-uploaded-do-not-move" tabindex="-1">Files already uploaded do not move <a class="header-anchor" href="#files-already-uploaded-do-not-move" aria-label="Permalink to &quot;Files already uploaded do not move&quot;">​</a></h3><p>Switching the driver changes where <strong>new</strong> uploads go. Files uploaded earlier stay where they were saved, but the store looks for them on the new storage, so copy them across before you switch, or they won&#39;t be found on the storefront.</p><h2 id="amazon-s3" tabindex="-1">Amazon S3 <a class="header-anchor" href="#amazon-s3" aria-label="Permalink to &quot;Amazon S3&quot;">​</a></h2><ol><li>Go to <strong>Configure &gt;&gt; File Management &gt;&gt; Amazon S3</strong>.</li><li>In <strong>Settings</strong>, enter the details described in the table.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',7)),o(r,{src:"/images/configure/file-management-s3.png",alt:"Amazon S3 screen of the File Management group with placeholder credentials"}),e[2]||(e[2]=t('<table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Access Key ID</strong></td><td>The access key ID of the account the bucket belongs to.</td></tr><tr><td><strong>Secret Access Key</strong></td><td>The secret paired with the access key ID.</td></tr><tr><td><strong>Region</strong></td><td>The region the bucket was created in, such as <code>us-east-1</code>.</td></tr><tr><td><strong>Bucket</strong></td><td>The name of the bucket files are stored in.</td></tr><tr><td><strong>URL</strong></td><td>The address files are served from. Leave it empty to use the address the service provides.</td></tr><tr><td><strong>Endpoint</strong></td><td>Only needed for a service other than Amazon S3, such as a self-hosted one. Leave it empty for Amazon S3.</td></tr><tr><td><strong>Use Path Style Endpoint</strong></td><td>Turn it on for a self-hosted service that addresses buckets as a path rather than a subdomain. Off by default.</td></tr></tbody></table><p>These settings are used only while the <strong>Default Storage Driver</strong> is <strong>Amazon S3</strong>. A field left empty uses the value from the server&#39;s environment file, if there is one.</p><h2 id="cloudflare-r2" tabindex="-1">Cloudflare R2 <a class="header-anchor" href="#cloudflare-r2" aria-label="Permalink to &quot;Cloudflare R2&quot;">​</a></h2><ol><li>Go to <strong>Configure &gt;&gt; File Management &gt;&gt; Cloudflare R2</strong>.</li><li>In <strong>Settings</strong>, enter the details described in the table.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',4)),o(r,{src:"/images/configure/file-management-r2.png",alt:"Cloudflare R2 screen of the File Management group with placeholder credentials"}),e[3]||(e[3]=t('<table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Account ID</strong></td><td>The Cloudflare account the bucket belongs to. The address of R2 is built from it, so no endpoint is needed.</td></tr><tr><td><strong>Access Key ID</strong></td><td>The access key ID of an R2 API token.</td></tr><tr><td><strong>Secret Access Key</strong></td><td>The secret paired with the access key ID.</td></tr><tr><td><strong>Bucket</strong></td><td>The name of the R2 bucket files are stored in.</td></tr><tr><td><strong>Public URL</strong></td><td>The address files are served from, either the bucket&#39;s public address or a custom domain. An R2 bucket is private until you turn on public access or connect a custom domain in Cloudflare. Enter that address here, or files can&#39;t be reached.</td></tr></tbody></table><p>These settings are used only while the <strong>Default Storage Driver</strong> is <strong>Cloudflare R2</strong>. A field left empty uses the value from the server&#39;s environment file, if there is one.</p><h2 id="differences-in-bagisto-2-4" tabindex="-1">Differences in Bagisto 2.4 <a class="header-anchor" href="#differences-in-bagisto-2-4" aria-label="Permalink to &quot;Differences in Bagisto 2.4&quot;">​</a></h2><p>Bagisto 2.4 has no <strong>File Management</strong> group.</p>',4))])}const b=a(l,[["render",d]]);export{p as __pageData,b as default};
